import re


def split_identifier(name):
    # zero-width split points: between a lowercase/digit and an uppercase,
    # and before the last capital of an acronym run (HTTP|Server)
    return re.split(r'(?<=[a-z0-9])(?=[A-Z])|(?<=[A-Z])(?=[A-Z][a-z])', name)


for name in ['camelCase', 'PascalCase', 'HTTPServerError', 'parseXMLDoc',
             'version2Beta', 'already']:
    print(name, '->', split_identifier(name))

import re


def add_commas(n):
    # \B: only between digits. The lookahead: the digits ahead of this
    # position must form complete groups of three up to the end.
    return re.sub(r'\B(?=(\d{3})+(?!\d))', ',', str(n))


for n in [999, 1000, 1234567, 12345678901]:
    print(n, '->', add_commas(n))

