# A hand-rolled model of what (a+)+$ must try on the input 'a'*n + 'b'.
# The outer group can split the run of a's into groups in every possible
# way (every "composition" of n). Each split is tried, then the trailing
# 'b' fails the $ anchor, so the engine moves to the next split.

def splits(n):
    if n == 0:
        return 1
    total = 0
    for first_group in range(1, n + 1):
        total += splits(n - first_group)
    return total


for n in range(1, 11):
    print(f'n={n:2d}  groupings tried before failing: {splits(n)}')

# (a|aa)+$ on 'a'*n + 'b': at each step the engine can consume one a
# or two, so the number of paths is the number of ways to tile n with
# 1s and 2s - the Fibonacci numbers. Slower growth than 2^n, still
# exponential: no constant factor saves it.

def splits(n):
    if n == 0:
        return 1
    total = 0
    for part in (1, 2):
        if part <= n:
            total += splits(n - part)
    return total


for n in range(1, 13):
    print(f'n={n:2d}  paths: {splits(n)}')

from functools import lru_cache

calls = 0


def splits(n):
    global calls
    calls += 1
    if n == 0:
        return 1
    return sum(splits(n - k) for k in range(1, n + 1))


print('naive  n=12:', splits(12), 'groupings,', calls, 'calls')

calls = 0


@lru_cache(maxsize=None)
def splits_memo(n):
    global calls
    calls += 1
    if n == 0:
        return 1
    return sum(splits_memo(n - k) for k in range(1, n + 1))


print('memo   n=12:', splits_memo(12), 'groupings,', calls, 'calls')

import re

s = 'plot(x, max(1, min(2, y)), z)'
print('regex finds:', re.findall(r'\([^()]*\)', s))


def outer_args(s):
    depth = 0
    args = []
    cur = ''
    for ch in s:
        if ch == '(':
            depth += 1
            if depth == 1:
                continue
        elif ch == ')':
            depth -= 1
            if depth == 0:
                args.append(cur)
                return [a.strip() for a in args]
        if depth == 1 and ch == ',':
            args.append(cur)
            cur = ''
        elif depth >= 1:
            cur += ch
    return [a.strip() for a in args]


print('parser gets:', outer_args(s))

