import re


def shape_ok(s):
    return re.fullmatch(r'97[89]\d{10}', s) is not None


def checksum_ok(s):
    total = sum(int(d) * (1 if i % 2 == 0 else 3) for i, d in enumerate(s[:12]))
    return (10 - total % 10) % 10 == int(s[12])


for s in ['9780306406157', '9780306406158', '9791090636071', '978030640615']:
    print(s, '| shape:', shape_ok(s),
          '| checksum:', checksum_ok(s) if shape_ok(s) else 'not reached')

import re


def shape_ok(s):
    return re.fullmatch(r'\d{13,19}', s) is not None


def luhn_ok(s):
    total = 0
    for i, ch in enumerate(reversed(s)):
        d = int(ch)
        if i % 2 == 1:
            d *= 2
            if d > 9:
                d -= 9
        total += d
    return total % 10 == 0


for s in ['4111111111111111', '4111111111111112', '378282246310005',
          '1234567890123456']:
    print(s, '| shape:', shape_ok(s), '| luhn:', luhn_ok(s))

import re
from datetime import datetime

pat = re.compile(r'\d{2}/\d{2}/\d{4}')


def is_real_date(s):
    try:
        datetime.strptime(s, '%m/%d/%Y')
        return True
    except ValueError:
        return False


for s in ['11/26/2026', '13/01/2026', '02/30/2026', '99/99/9999',
          '1/5/2026', '11/26/26']:
    print(s, '| pattern accepts:', pat.fullmatch(s) is not None,
          '| actually a date:', is_real_date(s))

import re

pat = re.compile(r'[\w.]+')


def naive_ok(name):
    return pat.fullmatch(name) is not None


def safe_ok(name):
    if not naive_ok(name):
        return False
    if name in ('.', '..'):  # current dir / parent dir are not filenames
        return False
    if '/' in name or '\\' in name:
        return False
    return True


names = ['report.pdf', 'data-2026.csv', '..', '.', '...', 'a..b',
         'my file.txt', 'etc/passwd']
for n in names:
    print(repr(n), '| naive pattern:', naive_ok(n), '| with dot checks:', safe_ok(n))

import re


def bump(m):
    return str(int(m.group()) + 1)


